// Dopasowanie e-maila lub telefonu z Levenshteinem 2 tolerancji.
function lev(a, b) {
  if (!a || !b) return Infinity;
  a = a.toLowerCase(); b = b.toLowerCase();
  const m = [];
  for (let i = 0; i <= b.length; i++) { m[i] = [i]; }
  for (let j = 0; j <= a.length; j++) { m[0][j] = j; }
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b[i-1] === a[j-1]) m[i][j] = m[i-1][j-1];
      else m[i][j] = Math.min(m[i-1][j-1]+1, m[i][j-1]+1, m[i-1][j]+1);
    }
  }
  return m[b.length][a.length];
}

const order = $node['Shopify Get Order'].json.order;
if (!order) {
  return [{ json: { verified: false, reason_code: 'E01_order_not_found' } }];
}

const input = $node['Normalize Input'].json;
const storedEmail = (order.email || order.customer?.email || '').toLowerCase();
const storedPhone = (order.phone || order.customer?.phone || '').replace(/\D/g, '');

let emailMatch = false;
if (input.email && storedEmail) {
  emailMatch = lev(input.email, storedEmail) <= 2;
}

let phoneMatch = false;
if (input.phone_last_4 && storedPhone) {
  phoneMatch = storedPhone.endsWith(input.phone_last_4);
}

const verified = emailMatch || phoneMatch;

return [{
  json: {
    verified,
    reason_code: verified ? 'ok' : 'E01_identity_mismatch',
    order_id: order.id.toString(),
    order_status: order.financial_status,
    fulfillment_status: order.fulfillment_status,
    tracking_number: order.fulfillments?.[0]?.tracking_number || null,
    tracking_company: order.fulfillments?.[0]?.tracking_company || null
  }
}];
